      @mouseenter="holdDockPin"
      @mouseleave="releaseDockPin"
    >
      <router-link to="/" custom v-slot="{ href }">
        <a :href="href" class="margin-dock-home" aria-label="Henry Wang, home" @pointerdown="beginHomeIdentityPress" @pointercancel="cancelHomeIdentityPress" @pointerleave="cancelHomeIdentityPress" @click.prevent="markTabNav(); navigateHomeWithPress($event, { introduction: true })">
          <span class="margin-dock-identity">H.W.</span>
          <small class="margin-dock-subtitle">Explore. Understand. Build.</small>
        </a>
      </router-link>
      <FittedMarginTitle ref="marginDockTitle" :title="dockPage.title" :detail="dockPage.isDetail" />
    </aside>
    <nav
      class="margin-dock-controls"
      v-show="marginDockActive && !previewMode && !isRoomRoute"
      aria-label="Persistent site controls"
      @mouseenter="holdDockPin"
      @mouseleave="releaseDockPin"
    >
      <div class="margin-dock-control-zone margin-dock-theme-zone">
        <button data-theme-control class="site-control margin-dock-control margin-dock-theme" type="button" :aria-label="dockThemeLabel" @pointerup="releaseDockPointerFocus" @click="toggleThemeFromDock">
          <i :class="dockThemeIconClass" aria-hidden="true"></i>
        </button>
      </div>
      <div class="margin-dock-control-zone margin-dock-search-zone">
        <button class="site-control margin-dock-control margin-dock-search" type="button" aria-label="Ask or search" @pointerup="releaseDockPointerFocus" @click="openSearch">
          <i class="fa fa-search" aria-hidden="true"></i>
        </button>
      </div>
      <div class="margin-dock-control-zone margin-dock-music-zone">
        <button data-music-control class="site-control margin-dock-control margin-dock-music" type="button" :aria-label="dockMusicLabel" @pointerup="releaseDockPointerFocus" @click="toggleMusicFromDock">
          <i :class="dockMusicIconClass" aria-hidden="true"></i>
        </button>
      </div>
    </nav>
    <MusicControls />
    <div class="content-container" :class="{ 'cv-route': isCv, 'view-source-return-active': !!viewReturnTarget }">
      <transition name="view-return">
        <div v-if="viewReturnTarget && !previewMode" class="view-return-slot">
          <button
            type="button"
            class="view-return-control"
            aria-label="Back to the View you came from"
            @click="returnToSourceView"
          >
            <span class="view-return-arrow" aria-hidden="true">←</span>
            <span>Back to View</span>
          </button>
        </div>
      </transition>
      <router-view v-slot="{ Component }">
        <transition :name="routeTransitionName" mode="out-in" @before-enter="beforeRouteEnter" @after-enter="finishRouteProgressTransition">
          <keep-alive :include="viewOriginCache">
            <component :is="Component" @page-title="routePageTitle = $event" />
          </keep-alive>
        </transition>
      </router-view>
      <SourceViewLinks
        v-if="detailSourceId && !previewMode && !isRoomRoute"
        class="detail-source-views"
        :source-id="detailSourceId"
      />
    </div>
    <footer class="footer" :class="{ 'home-direct-nav': directHomeNavHidden, 'home-route': isArchivedHome, 'initial-chrome-pending': !initialChromeReady }" v-show="!cvChromeHidden && !previewMode && !isRoomRoute">
      <a href="https://www.instagram.com/henry_w_hy/" target="_blank">
        <i class="fab fa-instagram" aria-hidden="true"></i>
      </a>
      <a href="https://www.linkedin.com/in/henrywhy/" target="_blank">
        <i class="fab fa-linkedin" aria-hidden="true"></i>
      </a>
      <a href="https://github.com/henryhyw/" target="_blank">
        <i class="fab fa-github" aria-hidden="true"></i>
      </a>
      <router-link to="/cv" title="CV" aria-label="CV">
        <i class="far fa-file-alt" aria-hidden="true"></i>
      </router-link>
      <div class="footer-description">
        <a><router-link to="/home">H.W. | Explore. Understand. Build.</router-link></a>
      </div>
    </footer>
    <SearchPalette v-if="!isRoomRoute" ref="search" @ai-complete="showAiCompletion" />
    <teleport :to="viewNoticeHost || 'body'">
      <transition name="ai-ready">
        <aside
          v-if="showViewJobNotice"
          class="ai-ready-notice ai-compose-notice"
          :class="{ 'is-museum-notice': viewNoticeHost }"
        >
          <ViewComposeProgress v-if="viewNoticeHost" compact :inline="false" :started-at="activeViewJob.startedAt" />
          <button
            v-else
            class="ai-compose-notice-button"
            type="button"
            aria-label="Open View composition progress"
            @click="openActiveViewJob"
          >
            <ViewComposeProgress compact :inline="false" :started-at="activeViewJob.startedAt" />
          </button>
        </aside>
      </transition>
      <transition name="ai-ready">
        <aside
          v-if="aiCompletion"
          class="ai-ready-notice"
          :class="{ 'is-museum-notice': viewNoticeHost }"
          role="status"
          aria-live="polite"
          aria-atomic="true"
        >
          <button class="ai-ready-main" type="button" @click="openAiCompletion">
            <span class="ai-ready-mark" aria-hidden="true">✦</span>
            <span class="ai-ready-copy">
              <strong>{{ aiCompletion.failed ? 'Your View needs another try' : (aiCompletion.kind === 'view' ? 'Your View is ready' : 'Your answer is ready') }}</strong>
              <span>{{ aiCompletion.label }}</span>
            </span>
            <span class="ai-ready-arrow" aria-hidden="true">→</span>
          </button>
          <button class="ai-ready-dismiss" type="button" aria-label="Dismiss" @click="aiCompletion = null">×</button>
        </aside>
      </transition>
    </teleport>
  </div>
</template>

<script>
import { isMuseumRoute, rememberMuseumOrigin, prefersMuseum } from './utils/viewMuseumSession';
import { revealViewTransition } from './utils/viewPresentationTransition';
import { isHomeIntroduction, requestHomeIntroduction } from './utils/homeEntrance';
import { marginDockFits } from './utils/marginDockLayout';
import { projectById } from './data/projects';
import SearchPalette from './components/SearchPalette.vue';
import { consumeAskSourceDeparture, loadHomeAskSnapshot, saveHomeAskSnapshot } from './utils/askReturn.js';
import SourceViewLinks from './components/ui/SourceViewLinks.vue';
import AiViewTerm from './components/ui/AiViewTerm.vue';
import FittedMarginTitle from './components/ui/FittedMarginTitle.vue';
import ViewComposeProgress from './components/view/ViewComposeProgress.vue';
import { viewProgressPresence } from './utils/viewProgressPresence';
import MobileMenuGlyph from './components/ui/MobileMenuGlyph.vue';
import MusicControls from './components/ui/MusicControls.vue';
import IdentityMark from './components/ui/IdentityMark.vue';
import { initCircularMediaRails } from './utils/mediaRails';
import {
  addAskTurn,
  clearSiteOrigin,
  consumeTabNavigation,
  loadAskSession,
  getSiteOrigin,
  markTabNavigation,
  prepareCollectionReturn,
  setPendingViewReturnScroll,
  setAskOrigin,
  setAskView,
  setSiteOrigin,
  setViewOriginRoute,
} from './utils/askSession';
import { candidatesForView } from './utils/viewRetrieval';
import { sanitizeViewResponse, validateViewResponse } from './utils/viewValidation';
import { clearViewJob, loadViewJob, resumeViewJob, viewComposeState } from './utils/viewSite';
import { settleScrollToY } from './utils/anchorLanding';
import { clearRouteReturn, getRouteReturn, markReturnRouteEntered, markRouteArrived, prepareRouteReturn } from './utils/routeScroll';
import { animate } from 'motion';

// The dock elements only ever translate (resting transforms are pure
// translateY), so the live on-screen offset is just the matrix translation.
function currentTranslation(element) {
  try {
    const m = new DOMMatrix(getComputedStyle(element).transform);
    return { x: m.m41, y: m.m42 };
  } catch (e) {
    return { x: 0, y: 0 };
  }
}

function isGeneratedViewPath(path) {
  const value = String(path || '');
  return value === '/view' || value.startsWith('/view/');
}

function siteOriginLabel(from) {
  if (from.path === '/' || from.path === '/home') {
    const index = document.getElementById('story-index');
    if (index && index.getBoundingClientRect().top <= window.innerHeight * 0.42) return 'Index';
    return 'Home';
  }
  if (from.path === '/projects') return 'Builds';
  if (from.path === '/views') return document.querySelector('.view-museum[open]') ? 'Gallery' : 'Views';
  const meta = String((from.meta && from.meta.title) || '');
  const name = meta.replace(/\s*-\s*H\.W\.\s*$/, '').trim();
  return name || (String(from.path).split('/').filter(Boolean).pop() || 'Home');
}

export default {
  name: 'App',
  components: { FittedMarginTitle, AiViewTerm, MobileMenuGlyph, MusicControls, IdentityMark, SearchPalette, SourceViewLinks, ViewComposeProgress },
  data() {
    return {
      scrollPct: 0,
      routeProgressPending: false,
      navTabsLayout: 'one',
      cvChromeHidden: false,
      marginDockActive: false,
      routePageTitle: { path: '', title: '' },
      marginDockPinned: false,
      dockHoverCount: 0,
      dockThemeIconClass: 'fa fa-moon',
      dockThemeLabel: 'Toggle theme',
      dockMusicIconClass: 'fa fa-compact-disc',
      dockMusicLabel: 'Play music',
      directHomeNavHidden: false,
      homeArrivalPending: typeof window !== 'undefined'
        && isHomeIntroduction(window.location.hash)
        && !window.matchMedia('(prefers-reduced-motion: reduce)').matches,
      initialChromeReady:
        typeof window === 'undefined'
        || isHomeIntroduction(window.location.hash)
        || /^#\/(?:$|home(?:-concept)?(?:$|[?#]))/.test(window.location.hash || ''),
      mobileHomeHeaderReady:
        typeof window === 'undefined'
        || !/^#\/(?:$|home(?:-concept)?(?:$|[?#]))/.test(window.location.hash || ''),
      homeVideoCursor: false,
      viewOriginCache: [],
      viewReturnTarget: '',
      viewReturnScrollY: 0,
      siteBackTarget: '',
      siteBackLabel: '',
      siteBackScrollY: 0,
      siteBackAskReturn: false,
      aiCompletion: null,
      viewJobNotice: null,
      mobileMenuOpen: false,
      mobileMenuClosing: false,
      mobileMenuNavigating: false,
      mobileMenuItems: [
        { to: '/home', label: 'Home', index: 0 },
        { to: '/education', label: 'Study', index: 1 },
        { to: '/experience', label: 'Work', index: 2 },
        { to: '/research', label: 'Research', index: 3 },
        { to: '/projects', label: 'Builds', index: 4 },
        { to: '/fragments', label: 'Fragments', index: 5 },
        { to: '/views', label: 'Views', index: 6, view: true },
      ],
    };
  },
  computed: {
    dockPage() {
      const project = this.detailSourceId && projectById(this.detailSourceId.replace('projects:', ''));
      const tab = this.mobileMenuItems.find(({ to }) => to === this.$route.path);
      const viewTitle = this.routePageTitle.path === this.$route.path ? this.routePageTitle.title : '';
      const title = project?.title || (this.isGeneratedViewRoute
        ? viewTitle
        : tab?.label || this.$route.meta.title?.replace(/ - (H\.W\.|Han-yu Wang)$/, '')) || '';
      return {
        title: title.split(/[:：]/, 1)[0].trim(),
        isDetail: !!project || this.isGeneratedViewRoute,
      };
    },
    previewMode() {
      return this.$route.query.preview === '1';
    },
    isArchivedHome() {
      return this.$route.path === '/archive/home';
    },
    isIntroRoot() {
      return this.isArchivedHome;
    },
    isHomeRoute() {
      return this.$route.path === '/' || this.$route.path === '/home' || this.isArchivedHome;
    },
    isCv() {
      return this.$route.path === '/cv';
    },
    isRoomRoute() {
      return this.$route.path === '/room';
    },
    isGeneratedViewRoute() {
      return isGeneratedViewPath(this.$route.path);
    },
    showScrollProgress() {
      return !this.isCv && this.$route.path !== '/home' && this.$route.path !== '/';
    },
    viewNoticeHost() { return viewProgressPresence.host; },
    activeViewJob() {
      return this.viewJobNotice || (viewComposeState.active ? { startedAt: viewComposeState.startedAt, surface: viewComposeState.surface } : null);
    },
    showViewJobNotice() {
      return !!this.activeViewJob && viewProgressPresence.inlineVisible === 0;
    },
    detailSourceId() {
      return {
        '/playbook': 'projects:insurance',
        '/ragflow-pipeline': 'projects:pwcRag',
        '/ai-it-operations': 'projects:pwcItOps',
        '/lexaday': 'projects:lexaday',
        '/dealtracker': 'projects:dealtracker',
        '/stride': 'projects:stride',
        '/scrollytelling': 'projects:scrollytelling',
        '/early': 'projects:early',
        '/aipersonalarchive': 'projects:searchstory',
        '/viewgallery': 'projects:searchstory',
      }[this.$route.path] || '';
    },
    routeTransitionName() {
      // The menu is already an opaque transition surface. Swapping the route
      // immediately beneath it prevents the previous page from reappearing as
      // the surface retracts.
      if (this.mobileMenuNavigating) return 'mobile-menu-route-swap';
      // Home owns a more detailed entrance sequence. A second route-level fade
      // made its mobile sections look painted once before their own reveal.
      if (this.isHomeRoute) return 'home-canvas';
      if (isGeneratedViewPath(this.$route.path)) return 'view-compose';
      return ['/research', '/projects', '/fragments', '/views'].includes(this.$route.path)
        ? 'fade-slide'
        : 'route-fade';
    }
  },
  watch: {
    '$route.query.preview'(value) {
      this.applyPreviewScrollContainment(value === '1');
    },
    '$route.path'(path, previousPath) {
      this.homeVideoCursor = false;
      if (path !== '/' && path !== '/home') {
        this.homeArrivalPending = false;
        this._cancelHomeIntroduction?.();
      }
      if (this.mobileMenuOpen && !this.mobileMenuNavigating) {
        this.closeMobileMenu({ restoreFocus: false });
      }
      if (previousPath === '/archive/home' && path !== '/archive/home') {
        this.$nextTick(this.resetIntroChromeStyles);
      }
      this.prepareMobileHomeHeaderMaterial(path);
    },
    isCv(onCv, wasCv) {
      if (this._cvChromeRevealTimer) {
        clearTimeout(this._cvChromeRevealTimer);
        this._cvChromeRevealTimer = null;
      }
      if (onCv) {
        // Hide the chrome the moment the route changes, before the page
        // transition runs, so the header never flashes on the way in.
        this.cvChromeHidden = true;
        this.pauseMusicForCv();
      } else if (wasCv || this.cvChromeHidden) {
        this._cvChromeRevealTimer = setTimeout(() => {
          this._cvChromeRevealTimer = null;
          if (!this.isCv) {
            this.cvChromeHidden = false;
            this.$nextTick(() => this.scheduleNavTabsLayout({ retries: 4 }));
          }
        }, 280);
      }
    }
  },
  mounted() {
    this._releaseHomeArrival = () => {
      this.homeArrivalPending = false;
      this._cancelHomeIntroduction?.();
    };
    window.addEventListener('home-entrance-prepared', this._releaseHomeArrival);
    this.prepareMobileHomeHeaderMaterial(this.$route.path);
    if (!this.initialChromeReady && !this.isCv) {
      this.$nextTick(() => {
        const header = this.$el.querySelector('.header');
        const footer = this.$el.querySelector('.footer');
        const reduceMotion = window.matchMedia
          && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (reduceMotion) {
          this.initialChromeReady = true;
        } else {
          [header, footer].forEach((element) => {
            if (!element) return;
            element.style.opacity = '0';
            element.style.transform = element === header ? 'translateY(-8px)' : 'translateY(8px)';
          });
          this.initialChromeReady = true;
          this.$nextTick(() => {
            this._initialChromeAnimations = [
              animate(header, { opacity: [0, 1], transform: ['translateY(-8px)', 'translateY(0px)'] }, { type: 'spring', bounce: 0, duration: 0.42 }),
              animate(footer, { opacity: [0, 1], transform: ['translateY(8px)', 'translateY(0px)'] }, { type: 'spring', bounce: 0, duration: 0.46, delay: 0.08 }),
            ];
          });
        }
      });
    }
    window.addEventListener('ask-origin-change', this.syncSiteBackState);
    window.addEventListener('museum-return-origin', this.returnFromMuseum);
    this._removeViewOriginGuard = this.$router.beforeEach((to, from) => {
      // Header tabs are top-level navigation: entering a page through a tab
      // clears any pending origin so no back control follows the visitor.
      const tabNavigation = consumeTabNavigation();
      const askDeparture = consumeAskSourceDeparture();
      this._askSourceNavigation = Boolean(askDeparture && askDeparture.route === from.fullPath);
      // The hall retains a separate origin across its own rooms and Read/Visit.
      // Capture header-tab arrivals too, before their normal back state clears.
      if (isMuseumRoute(to.path) && !isMuseumRoute(from.path) && from.matched.length && !to.query.embedded) {
        rememberMuseumOrigin({ route: from.fullPath, label: siteOriginLabel(from), scrollY: window.scrollY,
          collectionState: this.collectionOriginState(from), viewportAnchor: this.siteOriginViewportAnchor(from, to),
          ...(this._askSourceNavigation ? askDeparture : {}) });
      }
      if (this._askSourceNavigation) {
        setSiteOrigin({ collectionState: this.collectionOriginState(from), ...askDeparture });
      } else if (tabNavigation || (isMuseumRoute(to.path) && isMuseumRoute(from.path) && prefersMuseum())) {
        clearSiteOrigin();
      } else if (
        from.matched.length > 0
        && to.path !== from.path
      ) {
        // Any other cross-route jump records where the visitor came from and
        // their exact scroll position, so the destination can offer a precise
        // return. Museum travel keeps its separate hall origin.
        setSiteOrigin({
          route: from.fullPath,
          label: siteOriginLabel(from),
          scrollY: window.scrollY,
          collectionState: this.collectionOriginState(from),
          viewportAnchor: this.siteOriginViewportAnchor(from, to),
        });
      }
      const enteringView = isGeneratedViewPath(to.path) && !isGeneratedViewPath(from.path);
      // A fresh full load straight into a View (from.matched is empty) has no
      // in-app origin to record; the View page falls back to its ?from query.
      if (enteringView && from.matched.length > 0) {
        setViewOriginRoute(from.fullPath);
        const component = from.matched[from.matched.length - 1]?.components?.default;
        const componentName = component?.name || component?.__name || '';
        this.viewOriginCache = componentName ? [componentName] : [];
      } else if (!isGeneratedViewPath(to.path) && !isGeneratedViewPath(from.path)) {
        this.viewOriginCache = [];
      }
      return true;
    });
    this._removeViewReturnHook = this.$router.afterEach((to, from, failure) => {
      if (!failure && to.path !== from.path) {
        this.beginRouteProgressTransition();
        // Reused route components have no enter transition to wait for.
        const component = route => route.matched[route.matched.length - 1]?.components?.default;
        if (component(to) === component(from)) {
          this.finishRouteProgressTransition();
          this.$nextTick(() => requestAnimationFrame(() => requestAnimationFrame(() => markRouteArrived(to.fullPath))));
        }
      }
      // History state is available as soon as navigation commits. Sync before
      // the destination renders so its own back link never flashes beside the
